import { Project } from '../domain/project';
import { ProjectRepository, TaskFilters, TaskRepository, UserRepository } from '../domain/repositories';
import { Task } from '../domain/task';
import { User } from '../domain/user';

export class InMemoryUserRepository implements UserRepository {
  private readonly users = new Map<string, User>();
  private sequence = 0;

  public nextId(): string { return `user-${++this.sequence}`; }
  public save(user: User): void { this.users.set(user.id, user); }
  public findById(id: string): User | undefined { return this.users.get(id); }
}

export class InMemoryProjectRepository implements ProjectRepository {
  private readonly projects = new Map<string, Project>();
  private sequence = 0;

  public nextId(): string { return `project-${++this.sequence}`; }
  public save(project: Project): void { this.projects.set(project.id, project); }
  public findById(id: string): Project | undefined { return this.projects.get(id); }
}

export class InMemoryTaskRepository implements TaskRepository {
  private readonly tasks = new Map<string, Task>();
  private sequence = 0;

  public nextId(): string { return `task-${++this.sequence}`; }
  public save(task: Task): void { this.tasks.set(task.id, task); }
  public findById(id: string): Task | undefined { return this.tasks.get(id); }

  public findByProjectId(projectId: string, filters: TaskFilters): Task[] {
    return [...this.tasks.values()].filter((task) =>
      task.projectId === projectId &&
      (filters.status === undefined || task.getStatus().value === filters.status) &&
      (filters.assigneeId === undefined || task.assigneeId === filters.assigneeId),
    );
  }
}

